export function SpriteCB_UnderwaterSurfBlob(sprite: any): any {
  let blobSprite: any =gSprites[sprite.sSpriteId];

       
      if (((sprite.sTimer++) & 3) == 0)
          blobSprite.y2 += sprite.sBobY;
       
      if ((sprite.sTimer & 15) == 0)
          sprite.sBobY = -sprite.sBobY;
}

